blocks.example:
def level_of(line):
    parts = line.split(" ")
    return parts[2]

def is_bad(level):
    return level in ("ERROR", "FATAL")

lines = [
    "2026-11-10 09:00:00 INFO gateway: ok",
    "2026-11-10 09:40:01 FATAL db: too many connections",
    "2026-11-10 09:40:01 ERROR payment-svc: timeout",
]
for l in lines:
    lv = level_of(l)
    print(lv, is_bad(lv))

drills.solution:
def service_of(line):
    return line.split(" ")[3].rstrip(":")

lines = [
    "2026-11-10 09:00:00 INFO gateway: ok",
    "2026-11-10 09:40:01 FATAL db: too many connections",
    "2026-11-10 09:40:01 ERROR payment-svc: timeout",
]
for l in lines:
    print(service_of(l))

